package com.vynedam.stockai.security;
import com.vynedam.stockai.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest q,HttpServletResponse r,FilterChain c)throws ServletException,java.io.IOException{var h=q.getHeader(HttpHeaders.AUTHORIZATION);if(h==null||!h.startsWith("Bearer ")){c.doFilter(q,r);return;}try{var claims=jwt.parse(h.substring(7));var user=users.findById(claims.getSubject()).filter(u->u.active).orElseThrow();var auth=new UsernamePasswordAuthenticationToken(user.id,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+user.role.name())));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){SecurityContextHolder.clearContext();}c.doFilter(q,r);} }
